package co.edu.uco.seguridad.pdp.assignments.application.usecase.impl;
import co.edu.uco.seguridad.pdp.assignments.application.primaryport.request.ListApplicationAssignmentsPageRequest; import co.edu.uco.seguridad.pdp.assignments.application.primaryport.response.AssignmentResponse; import co.edu.uco.seguridad.pdp.assignments.application.secondaryport.repository.AssignmentRepository; import co.edu.uco.seguridad.pdp.assignments.application.usecase.ListApplicationRoleAssignmentsPageUseCase; import co.edu.uco.seguridad.pdp.commons.model.ResultPage; import reactor.core.publisher.Mono;
public final class ListApplicationRoleAssignmentsPageUseCaseImpl implements ListApplicationRoleAssignmentsPageUseCase { private final AssignmentRepository repository; public ListApplicationRoleAssignmentsPageUseCaseImpl(AssignmentRepository repository){this.repository=repository;} public Mono<ResultPage<AssignmentResponse>> execute(ListApplicationAssignmentsPageRequest i){return repository.findPageByApplication(i.tenantId(),i.applicationId(),i.window()).map(p->p.map(a->new AssignmentResponse(a.id(),a.userId(),a.tenantId(),a.applicationId(),a.roleId(),a.validity().validFrom(),a.validity().validUntil())));} }
